class Solution {
  private int[][] child;
  private int[] count;
  private int nodes;

  private void insert(int val, int delta) {
    int cur = 0;
    for (int b = 14; b >= 0; b--) {
      int bit = val >> b & 1;
      if (child[cur][bit] == 0) child[cur][bit] = ++nodes;
      cur = child[cur][bit];
      count[cur] += delta;
    }
  }

  private int maxXor(int val) {
    int cur = 0, res = 0;
    for (int b = 14; b >= 0; b--) {
      int want = (val >> b & 1) ^ 1;
      int next = child[cur][want];
      if (next != 0 && count[next] > 0) {
        res |= 1 << b;
        cur = next;
      } else cur = child[cur][want ^ 1];
    }
    return res;
  }

  public int maxXor(int[] nums, int k) {
    int n = nums.length;
    child = new int[n * 16 + 40][2];
    count = new int[n * 16 + 40];
    int[] pre = new int[n + 1];
    for (int i = 0; i < n; i++) pre[i + 1] = pre[i] ^ nums[i];
    int[] maxDq = new int[n], minDq = new int[n];
    int mh = 0, mt = 0, nh = 0, nt = 0, left = 0, best = 0;
    for (int r = 0; r < n; r++) {
      while (mt > mh && nums[maxDq[mt - 1]] <= nums[r]) mt--;
      maxDq[mt++] = r;
      while (nt > nh && nums[minDq[nt - 1]] >= nums[r]) nt--;
      minDq[nt++] = r;
      insert(pre[r], 1);
      while (nums[maxDq[mh]] - nums[minDq[nh]] > k) {
        insert(pre[left], -1);
        left++;
        if (maxDq[mh] < left) mh++;
        if (minDq[nh] < left) nh++;
      }
      best = Math.max(best, maxXor(pre[r + 1]));
    }
    return best;
  }
}
